mkitem!{# [doc = " Loads an integer of the desired type from a byte stream, in LE order. Uses"] # [doc = " `copy_nonoverlapping` to let the compiler generate the most efficient way"] # [doc = " to load it from a possibly unaligned address."] # [doc = ""] # [doc = " Safety: this performs unchecked indexing of `$buf` at"] # [doc = " `$i..$i+size_of::<$int_ty>()`, so that must be in-bounds."] macro_rules ! load_int_le { ($ buf : expr , $ i : expr , $ int_ty : ident) => { { debug_assert ! ($ i + size_of ::<$ int_ty > () <= $ buf . len ()) ; let mut data = 0 as $ int_ty ; ptr :: copy_nonoverlapping ($ buf . as_ptr () . add ($ i) , & mut data as * mut _ as * mut u8 , size_of ::<$ int_ty > () ,) ; data . to_le () } } ; }}

macro_rules! u8to64_le_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function u8to64_le in module {}", module_path!());
    };
}

mkfn!{
    u8to64_le_introspect!();
    # [doc = " Loads a u64 using up to 7 bytes of a byte slice. It looks clumsy but the"] # [doc = " `copy_nonoverlapping` calls that occur (via `load_int_le!`) all have fixed"] # [doc = " sizes and avoid calling `memcpy`, which is good for speed."] # [doc = ""] # [doc = " Safety: this performs unchecked indexing of `buf` at `start..start+len`, so"] # [doc = " that must be in-bounds."] # [inline] unsafe fn u8to64_le (buf : & [u8] , start : usize , len : usize) -> u64 { debug_assert ! (len < 8) ; let mut i = 0 ; let mut out = 0 ; if i + 3 < len { out = unsafe { load_int_le ! (buf , start + i , u32) } as u64 ; i += 4 ; } if i + 1 < len { out |= (unsafe { load_int_le ! (buf , start + i , u16) } as u64) << (i * 8) ; i += 2 } if i < len { out |= (unsafe { * buf . get_unchecked (start + i) } as u64) << (i * 8) ; i += 1 ; } debug_assert ! (i == len) ; out }
}
